def parse_age(text):
    if not (text.isascii() and text.isdigit()):
        raise ValueError('age must be digits only')
    age = int(text)
    if not 13 <= age <= 120:
        raise ValueError('age must be from 13 to 120')
    return age

for sample in ['42', '-5', '12', 'abc', '99999999999']:
